import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.Crpw6aS5.js";const k=JSON.parse('{"title":"GCC 11 链接报错：libfmt Dso missing from command line","description":"","frontmatter":{},"headers":[],"relativePath":"0-收集箱/3 问题记录/GCC11链接报错libfmt-Dso-missing-from-command-line.md","filePath":"0-收集箱/3 问题记录/GCC11链接报错libfmt-Dso-missing-from-command-line.md","lastUpdated":1786948858000}'),t={name:"0-收集箱/3 问题记录/GCC11链接报错libfmt-Dso-missing-from-command-line.md"};function l(h,s,r,d,p,o){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="gcc-11-链接报错-libfmt-dso-missing-from-command-line" tabindex="-1">GCC 11 链接报错：libfmt Dso missing from command line <a class="header-anchor" href="#gcc-11-链接报错-libfmt-dso-missing-from-command-line" aria-label="Permalink to &quot;GCC 11 链接报错：libfmt Dso missing from command line&quot;">​</a></h1> <h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2> <p>GCC 11.4 编译时链接报错：</p> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lib/aarch64-linux-gnu/libfmt.so.8: error adding symbols: Dso missing from command line</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>同样的代码和链接方式在 GCC 9.4 下编译正常。</p> <h2 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h2> <p>GCC 11 对应的 binutils 2.38+ 默认启用了更严格的 <code>--as-needed</code> 链接策略：</p> <ul><li><strong>GCC 9.4 / binutils 2.34</strong>：链接器对间接依赖的动态库较宽松，未显式声明的库如果被其他库拉进来也能通过</li> <li><strong>GCC 11.4 / binutils 2.38+</strong>：<code>--as-needed</code> 更激进，未被直接引用的库会被丢弃，间接依赖必须显式声明</li></ul> <p>GNU ld 不做反向依赖解析，动态库必须显式出现在链接命令中，且顺序要对（从左到右扫描）。GCC 9.4 能过是&quot;碰巧能跑&quot;，GCC 11.4 的行为才是符合规范的。</p> <h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2> <h3 id="_1-显式加-lfmt-推荐" tabindex="-1">1. 显式加 -lfmt（推荐） <a class="header-anchor" href="#_1-显式加-lfmt-推荐" aria-label="Permalink to &quot;1. 显式加 -lfmt（推荐）&quot;">​</a></h3> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> other.o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lfmt</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>注意</strong>：<code>-lfmt</code> 必须放在引用它的目标文件之后，顺序反了同样会报错。</p> <h3 id="_2-用-pkg-config" tabindex="-1">2. 用 pkg-config <a class="header-anchor" href="#_2-用-pkg-config" aria-label="Permalink to &quot;2. 用 pkg-config&quot;">​</a></h3> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> other.o</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pkg-config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --libs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fmt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_3-cmake" tabindex="-1">3. CMake <a class="header-anchor" href="#_3-cmake" aria-label="Permalink to &quot;3. CMake&quot;">​</a></h3> <div class="language-cmake vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">find_package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fmt REQUIRED)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_link_libraries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(your_target </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PRIVATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fmt::fmt)</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_4-间接依赖的情况" tabindex="-1">4. 间接依赖的情况 <a class="header-anchor" href="#_4-间接依赖的情况" aria-label="Permalink to &quot;4. 间接依赖的情况&quot;">​</a></h3> <p>代码没直接用 fmt，但某个库依赖了它，同样需要显式链接：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lyourlib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lfmt</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_5-临时绕过-不推荐" tabindex="-1">5. 临时绕过（不推荐） <a class="header-anchor" href="#_5-临时绕过-不推荐" aria-label="Permalink to &quot;5. 临时绕过（不推荐）&quot;">​</a></h3> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Wl,--no-as-needed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lfmt</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2> <p>GCC 版本升级后链接器变严格，隐式依赖的动态库必须显式声明。正确做法是补上 <code>-lfmt</code>，不要用 <code>--no-as-needed</code> 绕过。</p>`,41)])])}const m=a(t,[["render",l]]);export{k as __pageData,m as default};
